							// caller's admin/owner role was checked upstream.
							sql``
			}
    ORDER BY last_activity_at DESC NULLS LAST, created_at DESC
  `;
	return rows.map((r) => ({
		platform: r.platform,
		conversationId: r.conversation_id,
		threadId: r.thread_id,
		kind: r.kind,
		userId: r.user_id,
		title: r.title,
