import { useMemo } from "react";
import { AgentChatPanelSkeleton } from "@/components/agents/agent-loading-shells";
import { AgentThread } from "@/components/agents/agent-thread";
import {
	type ChatMessage,
	ReadOnlyChatProvider,
	serverRowToMessage,
} from "@/components/agents/lobu-chat-store";
import { PlatformIcon } from "@/components/agents/platform-icon";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useConversationMessages } from "@/lib/api/agents";
import { useConnections } from "@/lib/api/connections";

const PLATFORM_LABEL: Record<string, string> = {
	slack: "Slack",
	telegram: "Telegram",
	whatsapp: "WhatsApp",
	discord: "Discord",
	web: "Web",
};

type ChatMetadata = { teamId?: string; teamName?: string };

/**
 * Deep link back to the originating conversation so the user can reply to the
 * agent on the source platform — these transcripts are read-only in the app.
 */
function platformConversationLink(
	platform: string,
	channelId: string | undefined,
	chatMetadata: ChatMetadata | undefined,
): string | null {
	if (platform === "slack" && chatMetadata?.teamId && channelId) {
		return `https://app.slack.com/client/${chatMetadata.teamId}/${channelId}`;
	}
	return null;
}

/**
 * Read-only view of a platform conversation (Slack, Telegram, …). These aren't
 * routable through the app chat composer, so we render the transcript via the
 * same read-only thread used for watcher runs, with a footer that links back to
 * the source platform where the user can actually talk to the agent.
 */
export function AgentConversationRoute({
	owner,
	agentId,
	conversationId,
}: {
	owner: string;
	agentId: string;
	conversationId: string;
}) {
	const { data: rows = [], isLoading } = useConversationMessages(
		agentId,
		conversationId,
		{ orgSlug: owner },
	);
	const messages = useMemo(
		() =>
			rows
				.map((row) => serverRowToMessage(row, { showToolCalls: true }))
				.filter((m): m is ChatMessage => m !== null),
		[rows],
	);

	const [platform, channelId] = conversationId.split(":");
	const platformLabel = PLATFORM_LABEL[platform] ?? "the source app";

	const { org } = useCurrentOrg();
	const { data: connections = [] } = useConnections(org?.id ?? "", {
		connectorKey: platform,
	});
	const chatMetadata = (
		connections[0]?.config as { chatMetadata?: ChatMetadata } | null | undefined
	)?.chatMetadata;
	const replyLink = platformConversationLink(platform, channelId, chatMetadata);

	return (
		<div className="mx-auto flex min-h-0 w-full max-w-3xl flex-1 flex-col pb-6">
			{isLoading ? (
				<AgentChatPanelSkeleton readOnly />
			) : messages.length === 0 ? (
				<p className="text-sm text-muted-foreground">
					No messages in this conversation.
				</p>
			) : (
				<div className="flex min-h-0 min-w-0 flex-1 flex-col">
					<ReadOnlyChatProvider messages={messages}>
						<AgentThread readOnly />
					</ReadOnlyChatProvider>
					{replyLink ? (
						<a
							href={replyLink}
							target="_blank"
							rel="noopener noreferrer"
							className="mt-4 flex items-center gap-3 rounded-lg border border-border bg-muted/40 px-4 py-3 text-sm transition-colors hover:bg-muted"
						>
							<PlatformIcon platform={platform} className="size-5 shrink-0" />
							<span className="text-muted-foreground">
								This is a read-only copy. Continue the conversation with this
								agent in {platformLabel}.
							</span>
							<span className="ml-auto shrink-0 whitespace-nowrap font-medium text-foreground">
								Open {platformLabel} →
							</span>
						</a>
					) : null}
				</div>
			)}

