export default async (ctx, client) => {
  const nav = await client.operations.execute({
    connection_id: 432,
    operation_key: "navigate",
    input: { url: "https://app.lobu.ai/", open_in_new_tab: true, wait_for_load: true },
  });
  const tab = nav.output.tab_id;
  const r = await client.operations.execute({
    connection_id: 432,
    operation_key: "evaluate",
    input: {
      tab_id: tab,
      await_promise: true,
      expression: `(async () => {
        await new Promise(r => setTimeout(r, 3500));
        const links = [...document.querySelectorAll('a[href]')].map(a => a.getAttribute('href'));
        return { url: location.href, conv: links.filter(h => h && h.includes('/conversations/')).slice(0,10), agents: links.filter(h => h && h.includes('/agents/')).slice(0,10), body: document.body.innerText.slice(0, 500) };
      })()`,
    },
  });
  return { tab, out: r.output };
}

export default async (ctx, client) => {
  const r = await client.operations.execute({
    connection_id: 432,
    operation_key: "evaluate",
    input: {
      tab_id: 558570937,
      await_promise: true,
