        history.pushState({}, '', '/buremba/agents/personal-agent/chat');
        window.dispatchEvent(new PopStateEvent('popstate'));
        await new Promise(r => setTimeout(r, 5000));
        function reddish(rgb) {
          const m = rgb && rgb.match(/rgba?\\(([^)]+)\\)/);
          if (!m) return false;
