        function redish(c) {
          if (!c) return false;
          let m = c.match(/^oklch\\(([-\\d.]+)[^\\d-]+([-\\d.]+)[^\\d-]+([-\\d.]+)/);
          if (m) {
            const C = parseFloat(m[2]), H = parseFloat(m[3]);
            const a = c.match(/\\/\\s*([\\d.]+)/);
            if (a && parseFloat(a[1]) < 0.02) return false;
            return C > 0.04 && ((H >= 5 && H <= 50) || (H >= 340 && H <= 360));
