          m = c.match(/rgba?\\(([^)]+)\\)/);
          if (!m) return false;
          const p = m[1].split(',').map(parseFloat);
          if (p.length > 3 && p[3] < 0.02) return false;
          return p[0] > 80 && p[0] > p[1] * 1.15 && p[0] > p[2] * 1.15;
