          out[a] = (d.threads || []).map(t => ({ id: t.id, platform: t.platform, title: (t.title||'').slice(0,40), behaviorId: t.behaviorId ?? null }));
        }
        return out;
      })()`,
    },
  });
  return { tab, out: r.output };
}

