/** A conversation's origin class, mirroring how the listing partitions ids. */
export type ConversationKind = "owned" | "platform" | "behavior";

/** Watcher RUN conversation id shape: `{agentId}_watcher_{id}_run_{runId}`.
 *  This is a session key, not a conversation key — it is unique per RUN because
 *  each run is a fresh one-shot session, and it is the worker-dispatch/SSE
 *  owner-routing key that {@link parseBehaviorRunConversationId} reads a
 *  Behavior's identity out of. A run id must NEVER get a `conversations` row;
 *  the Behavior's LISTING row is keyed per behavior by
 *  {@link behaviorConversationId}. */
const WATCHER_CONVERSATION_ID = /_watcher_\d+_run_\d+$/;

export function isWatcherConversationId(conversationId: string): boolean {
	return WATCHER_CONVERSATION_ID.test(conversationId);
}

/** Stable listing key for a Behavior — one row per Behavior across all its runs.
 *  Colon-delimited like the platform ids it sits beside; the colon ban applies
 *  only to the BullMQ job id built by `buildApiConversationId`, never here. */
export function behaviorConversationId(behaviorId: number): string {
	return `behavior:${behaviorId}`;
}

/** Inverse of {@link behaviorConversationId}. Returns null for any other id. */
export function parseBehaviorConversationId(
	conversationId: string,
): number | null {
	const match = /^behavior:(\d+)$/.exec(conversationId);
	if (!match) return null;
	const id = Number(match[1]);
	return Number.isSafeInteger(id) && id > 0 ? id : null;
}

/**
 * Materialize (or refresh) the listing row for a Behavior. Called when a run
 * checkpoints as completed — the same event the old derive path aggregated, so
 * the listed timestamp is unchanged; it is now written once instead of being
 * recomputed on every sidebar render.
 *
 * Unlike {@link upsertConversation} this overwrites `title`: the Behavior's name
 * is authoritative and current, where a conversation's title is a frozen first
 * message. {@link syncBehaviorConversation} keeps it fresh across renames
 * between runs.
 *
 * Failures are swallowed for the same reason as `upsertConversation` — a
 * listing hiccup must never fail a run's terminal checkpoint.
 */
export async function upsertBehaviorConversation(row: {
	organizationId: string;
	agentId: string;
	behaviorId: number;
	title: string | null;
	lastActivityAt: Date;
}): Promise<void> {
	try {
		const sql = getDb();
		await sql`
      INSERT INTO public.conversations (
        organization_id, agent_id, platform, conversation_id, thread_id,
        kind, user_id, title, is_direct, last_activity_at
      ) VALUES (
        ${row.organizationId}, ${row.agentId}, 'behavior',
        ${behaviorConversationId(row.behaviorId)}, NULL, 'behavior',
        NULL, ${row.title}, NULL, ${row.lastActivityAt}
      )
      ON CONFLICT (organization_id, agent_id, platform, conversation_id)
      DO UPDATE SET
        last_activity_at = GREATEST(
          public.conversations.last_activity_at, EXCLUDED.last_activity_at
        ),
        title = COALESCE(EXCLUDED.title, public.conversations.title),
        -- A Behavior that runs again is live again: clear any soft-delete left
        -- by an earlier archive so the row re-enters conversations_listing.
        archived_at = NULL,
        updated_at = now()
    `;
	} catch (err) {
		logger.warn(
			{
				err,
				organizationId: row.organizationId,
				agentId: row.agentId,
				behaviorId: row.behaviorId,
			},
			"upsertBehaviorConversation failed — Behavior not materialized for this run",
		);
	}
}

/**
 * Mirror a Behavior's definition change onto its listing row: renames refresh
 * the title, archive soft-deletes (the `conversations_listing` partial index is
 * `WHERE archived_at IS NULL`, so the row leaves the sidebar), unarchive
 * restores it.
 *
 * This is what makes the listing lifecycle-aware. The derive path could not do
 * it at all: it read immutable run history, and archiving a Behavior does not
 * unmake its past runs.
 *
 * No-ops when the Behavior has no row yet — a Behavior that has never completed
 * a run has nothing to list.
 */
export async function syncBehaviorConversation(args: {
	organizationId: string;
	behaviorId: number;
	title?: string | null;
	archived?: boolean;
}): Promise<void> {
	try {
		const sql = getDb();
		await sql`
      UPDATE public.conversations
      SET title = COALESCE(${args.title ?? null}, title),
          archived_at = CASE
            WHEN ${args.archived ?? null}::boolean IS NULL THEN archived_at
            WHEN ${args.archived ?? null}::boolean THEN COALESCE(archived_at, now())
            ELSE NULL
          END,
          updated_at = now()
      WHERE organization_id = ${args.organizationId}
        AND platform = 'behavior'
        AND conversation_id = ${behaviorConversationId(args.behaviorId)}
    `;
	} catch (err) {
		logger.warn(
			{ err, organizationId: args.organizationId, behaviorId: args.behaviorId },
			"syncBehaviorConversation failed — listing row may show a stale name or an archived Behavior",
		);
	}
}

