import { getDb } from "../../db/client.js";
import { parseBehaviorRunConversationId } from "../permissions/behavior-run-intent.js";

const logger = createLogger("worker-transcript");

/**
 * Stamp the Behavior's last completed run so the sidebar can order Behaviors by
 * a stored value instead of aggregating run history on every read.
 *
 * The checkpoint is deliberately the same event the removed query selected on —
 * `terminal_status='completed'` for a `_watcher_<id>_run_<id>` conversation — so
 * the listed timestamps are unchanged, just precomputed.
 *
 * `name` and `status` are NOT copied anywhere: the listing reads them live off
 * this same row, which is why archiving or renaming a Behavior needs no
 * synchronisation at all.
 *
 * `intent.runId !== runId` rejects a conversation id whose packed run id
 * disagrees with the run this snapshot authenticated as — the id is only
 * trustworthy when the two halves agree.
 *
 * Best-effort: a listing write must never fail the run's terminal checkpoint.
 */
async function stampBehaviorLastRun(args: {
  organizationId: string;
  agentId: string;
  conversationId: string;
  terminalStatus: string;
  runId: number;
  completedAt: Date;
}): Promise<void> {
  if (args.terminalStatus !== "completed") return;
  const intent = parseBehaviorRunConversationId(args.conversationId);
  if (!intent || intent.runId !== args.runId) return;

  // GREATEST so an out-of-order checkpoint (a retry landing after a later run
  // already stamped) cannot move the Behavior backwards in the listing.
  await getDb()`
    UPDATE public.watchers
    SET last_run_completed_at = GREATEST(
          COALESCE(last_run_completed_at, ${args.completedAt}), ${args.completedAt}
        )
    WHERE id = ${intent.behaviorId}
      AND organization_id = ${args.organizationId}
      AND agent_id = ${args.agentId}
  `;
}

