	// Behavior activity is a UNION from `watchers`, one entry per BEHAVIOR (not
	// per run). Watcher RUNS still deliberately get no `conversations` row — that
	// id is a session key whose exact `..._watcher_<id>_run_<id>` shape downstream
	// correlation depends on — and a Behavior is not a conversation either, so it
	// gets no row there.
	//
	// This replaces a read-time `GROUP BY` + `regexp_match` + leading-wildcard
	// `LIKE` over `agent_transcript_snapshot`, which was unindexable, grew with
	// run history forever, and — reading immutable run rows — had no way to drop
	// an archived Behavior (22 of 26 rows on one prod agent were archived).
	// `watchers` is a bounded config table, so this is an indexed select, not the
	// history aggregation AGENTS.md forbids on a request path.
	//
	// `status` and `name` are read LIVE from this row, which is exactly why
	// archiving or renaming a Behavior needs no synchronisation anywhere.
	if (scope === "all") {
		const sql = getDb();
		const behaviorRows = await sql<{
			id: number;
			name: string | null;
			last_run_completed_at: Date;
		}>`
      SELECT id, name, last_run_completed_at
      FROM public.watchers
      WHERE organization_id = ${organizationId}
        AND agent_id = ${agentId}
        AND status = 'active'
        AND last_run_completed_at IS NOT NULL
      ORDER BY last_run_completed_at DESC
    `;
		for (const row of behaviorRows) {
			// `watcher_<id>` is the key the panel has always rendered and routed on.
			const key = `watcher_${row.id}`;
			const at = row.last_run_completed_at.getTime();
			byKey.set(key, {
				id: key,
				title: row.name ?? `Behavior ${row.id}`,
				// Preserves the derived contract: a Behavior entry represents latest
				// activity, so both timestamps track the last completed run.
				createdAt: at,
				updatedAt: at,
				platform: "behavior",
				conversationId: key,
				behaviorId: row.id,
			});
		}
	}

		// The stamp a completed run leaves (`stampBehaviorLastRun`). The Behavior's
		// sidebar entry is READ from this column, not re-derived from the snapshot
		// above on every request.
