	orgSlug: string | null | undefined,
	agentId: string,
	options?: { strict?: boolean },
) {
	return {
		queryKey: ["agent-threads", orgSlug, agentId] as const,
		queryFn: () => fetchAgentThreads(agentId, orgSlug, options),
		staleTime: 15_000,
	};
}

