// Executing a Behavior writes TWO `runs` rows, and the fixture has to keep
// them distinct or it hides a whole class of bug: the `run_type='behavior'`
// job, whose id is what gets packed into `_run_<id>` of the conversation
// id, and the `run_type='chat_message'` turn the dispatcher queues for it —
// the id the worker token and the snapshot body carry. Deriving the
// conversation id from the id the token also carries makes the two spaces
// coincide, which no production checkpoint ever does (measured against a
// booted server: conversation `…_watcher_1_run_109` checkpoints under
// `runId=112`).
const checkpoint = async (terminalStatus: "completed" | "failed") => {
  const behaviorRunId = await insertRun({
    organizationId: orgId,
    agentId,
    conversationId: "pending-behavior-conversation-id",
    runType: "behavior",
  });
  const conversationId = `${agentId}_watcher_${behaviorId}_run_${behaviorRunId}`;
  await sql`
    UPDATE public.runs
    SET watcher_id = ${behaviorId}
    WHERE id = ${behaviorRunId}
  `;
  const turnRunId = await insertRun({
    organizationId: orgId,
    agentId,
    conversationId,
  });
  const token = mintWorkerToken({
    organizationId: orgId,
    agentId,
    conversationId,
    runId: turnRunId,
  });
  const response = await callRoute("POST", "/snapshot", token, {
    terminalStatus,
    snapshotJsonl: `{"type":"session","id":"behavior-${behaviorRunId}"}\n`,
    runId: turnRunId,
  });
  expect(response.status).toBe(200);
  // Settle the run as production does. `idx_runs_executing_per_behavior`
  // permits only one in-flight run per Behavior, so leaving it active would
  // make the next checkpoint in this test collide.
  await sql`
    UPDATE public.runs
    SET status = ${terminalStatus}, completed_at = now()
    WHERE id IN (${behaviorRunId}, ${turnRunId})
  `;
  return turnRunId;
};

