    fable|opus|claude-opus-?*) return 0 ;;
    *)
      echo "invalid CLAUDE_REVIEW_MODEL=$1 (only fable, opus, or a claude-opus-* model is allowed)" >&2
      return 2
      ;;
  esac
}

review_should_retry_inline() {
